{
  "correction_rules": [
    "Reduce forecast overshoots following sharp upward spikes in price (especially after sentiment > 0.00).",
    "Adjust forecasts downward when sentiment is negative (sentiment < 0.00) or near-zero, indicating bearish bias.",
    "Apply mean reversion correction: if forecast is significantly above recent 7-day average, reduce by 5-10%.",
    "Increase downward bias when historical 30-day mean is below forecast, especially if sentiment is neutral or negative.",
    "Lag correction: if true outcome is below forecast, reduce next forecast by 3-5% to account for delayed market reaction.",
    "Avoid overconfidence in early forecast periods — reduce forecast volatility when sentiment is low or flat."
  ]
}
